import React, { useEffect, useState } from 'react';
import { getBookings, getParkingSpots, getParkingSlots } from '../services/api';
import { useAuth } from '../context/AuthContext';

const statusColor = (s) => {
  if (!s) return 'neutral';
  const sl = s.toLowerCase();
  if (sl.includes('confirm') || sl.includes('complete')) return 'success';
  if (sl.includes('pending') || sl.includes('hold')) return 'warning';
  if (sl.includes('cancel')) return 'danger';
  return 'neutral';
};

export default function LenderBookings() {
  const { currentUser } = useAuth();
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const load = async () => {
      try {
        const [allBookings, spots, slots] = await Promise.all([getBookings(), getParkingSpots(), getParkingSlots()]);
        const mySpotIds = spots.filter(s => s.user?.userId === currentUser.userId).map(s => s.spotId);
        const mySlotIds = slots.filter(sl => mySpotIds.includes(sl.spot?.spotId)).map(sl => sl.slotId);
        setBookings(allBookings.filter(b => mySlotIds.includes(b.slot?.slotId)));
      } catch {}
      setLoading(false);
    };
    load();
  }, [currentUser]);

  if (loading) return <div style={{ padding: 40 }}><div className="loader" /></div>;

  return (
    <div style={{ padding: '32px', maxWidth: '1100px', margin: '0 auto' }}>
      <div className="page-header">
        <h1>Bookings for My Spots</h1>
        <p>{bookings.length} bookings on your parking spots</p>
      </div>

      {bookings.length === 0 ? (
        <div className="empty-state"><div className="icon">📋</div><p>No bookings on your spots yet.</p></div>
      ) : (
        <div className="table-wrap">
          <table>
            <thead>
              <tr><th>Booking Code</th><th>User</th><th>Vehicle</th><th>Date</th><th>Duration</th><th>Amount</th><th>Status</th></tr>
            </thead>
            <tbody>
              {bookings.map(b => (
                <tr key={b.bookingId}>
                  <td style={{ fontFamily: 'monospace', color: 'var(--accent)' }}>{b.bookingCode || `#${b.bookingId}`}</td>
                  <td style={{ color: 'var(--text)' }}>{b.user?.name || `User #${b.user?.userId}`}</td>
                  <td>{b.vehicle?.vehicleNo || '—'}</td>
                  <td>{b.bookingDate}</td>
                  <td style={{ fontSize: '12px' }}>
                    {b.startTime ? new Date(b.startTime).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' }) : '—'} →{' '}
                    {b.endTime ? new Date(b.endTime).toLocaleTimeString('en-IN', { hour: '2-digit', minute: '2-digit' }) : '—'}
                  </td>
                  <td style={{ color: 'var(--warning)', fontWeight: 600 }}>₹{b.finalAmt || b.estimatedAmt}</td>
                  <td><span className={`badge badge-${statusColor(b.bookingStatus)}`}>{b.bookingStatus}</span></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
}
